arguments.argument:
sprite_index=global.unit_id_spr[unit_id, 2]

if instance_number(attack_unit)
{
    image_angle=point_direction(x, y, attack_unit.x, attack_unit.y)
    mp_potential_step(attack_unit.x, attack_unit.y, bullet_speed, 0)
    if instance_place(x, y, attack_unit)
    {
        if (global.player_control=player or (!fn_get_my_player_id(global.socket) and global.player_com[player]))
        {
            int=attack_unit.hp
            
            attack_unit.hp-=attack_power
            for(i=0; i!=attack_plus_number; i+=1){if attack_unit.unit_id=attack_plus_id[i]{attack_unit.hp-=attack_plus_power[i]; break}}
            
            int-=attack_unit.hp
            
            /*on*/buffer_clear(fnv_sned)
            write_uint(fnv_sned, attack_unit.on)
            write_uint(fnv_sned, int)
            fn_message_send(global.socket, send_other, 26)
            
            if instance_number(iid)
            {
                with(obj_unit)
                {
                    if distance_to_point(other.iid.x, other.iid.y)<other.attack_range+200 and ((4>player and other.player>=4) or (player>=4 and 4>other.player))
                    {
                        if attack_waits=1
                        {
                            attack_unit=other.iid
                            attack_waits=4
                            /*on*/buffer_clear(fnv_sned)
                            write_uint(fnv_sned, on)
                            write_uint(fnv_sned, attack_unit.on)
                            fn_message_send(global.socket, send_other, 25)
                        }
                    }
                }
            }
        }
        instance_destroy()
    }
}
else{instance_destroy()}
